require_once 'inc/db.php';require_once 'inc/auth.php';$msg=$msge='';
if($_SERVER['REQUEST_METHOD']==='POST'){$first=trim($_POST['firstname']??'');$last=trim($_POST['lastname']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');if(!$first||!$last||!filter_var($email,FILTER_VALIDATE_EMAIL)){$msge='Enter a valid name and email address.';}else{try{$fields='firstname=?,lastname=?,email=?,phone=?';$values=[$first,$last,$email,$phone];if(!empty($_POST['password'])){if(strlen($_POST['password'])<8){$msge='New password must contain at least 8 characters.';}else{$fields.=',password=?';$values[]=password_hash($_POST['password'],PASSWORD_DEFAULT);}}if(!$msge){$values[]=$_SESSION['user_id'];$db->prepare("UPDATE tbl_users SET $fields WHERE user_id=?")->execute($values);$_SESSION['firstname']=$first;$_SESSION['lastname']=$last;$msg='Profile updated.';}}catch(PDOException $e){$msge='That email is already in use.';}}}
$s=$db->prepare('SELECT * FROM tbl_users WHERE user_id=?');$s->execute([$_SESSION['user_id']]);$u=$s->fetch(PDO::FETCH_ASSOC);$page_title='My Profile';include 'inc/links.php';include 'inc/header.php';?>
<div class="inner-wrapper"><?php include 'inc/sidebar.php';?><section role="main" class="content-body"><?php include 'inc/inner-header.php';?><?php if($msg):?><div class="alert alert-success"><?php echo e($msg);?></div><?php endif;if($msge):?><div class="alert alert-danger"><?php echo e($msge);?></div><?php endif;?><section class="panel"><header class="panel-heading"><h2 class="panel-title">Account Details</h2></header><div class="panel-body"><form method="post" style="max-width:650px"><div class="row"><div class="col-sm-6 form-group"><label>First name</label><input required name="firstname" class="form-control" value="<?php echo e($u['firstname']);?>"></div><div class="col-sm-6 form-group"><label>Last name</label><input required name="lastname" class="form-control" value="<?php echo e($u['lastname']);?>"></div></div><div class="form-group"><label>Email</label><input required type="email" name="email" class="form-control" value="<?php echo e($u['email']);?>"></div><div class="form-group"><label>Phone</label><input name="phone" class="form-control" value="<?php echo e($u['phone']);?>"></div><div class="form-group"><label>New password <small>(leave blank to keep current password)</small></label><input type="password" minlength="8" name="password" class="form-control"></div><button class="btn btn-danger">Save Profile</button></form></div></section></section></div><?php include 'inc/scripts.php';?>
